import{z as o,x as n,o as e,c as s,q as t,j as B,D as a,d as A,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"缓存感知路由","description":"","frontmatter":{"title":"缓存感知路由","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-cache-aware-routing.md","filePath":"llm/sch-cache-aware-routing.md","lastUpdated":1791063341000}'),C={name:"llm/sch-cache-aware-routing.md"};function D(h,E,d,m,p,F){const l=n("Mermaid");return e(),s("div",null,[E[2]||(E[2]=t('<h1 id="缓存感知路由" tabindex="-1">缓存感知路由 <a class="header-anchor" href="#缓存感知路由" aria-label="Permalink to &quot;缓存感知路由&quot;">​</a></h1><div class="epigraph"><p>命中率不是运气，是放置：网关的每一次转发，都在决定这段前缀的全集群第二位作者是谁。</p><footer>—— 据 Kwon et al., SOSP 2023 的放置口径与 SGLang Router、Preble 的路由实践整理</footer></div><p><a href="/llm/sch-multi-lora">上一课</a>把适配器亲和写进路由的输入；本课展开路由的另一个输入：前缀缓存。单机内 KV 怎么留、怎么匹配，KV 课程已收束（<a href="/llm/kv-prefix-cache">前缀缓存与跨请求共享</a>、<a href="/llm/kv-map">KV 管理收束</a> 把「命中靠放置」列为决策单的第二刀）；本课把「放置」写成集群层的算法：入口怎么看见各副本的树、命中与负载怎么折中、软状态怎么维护。引擎内的树见 <a href="/llm/radix-attention">RadixAttention</a> 与 <a href="/llm/sglang-radix-tree">SGLang 前缀树</a>，入口路由器见 <a href="/llm/sglang-router">SGLang Router</a>、<a href="/llm/kv-aware-routing">KV 感知路由</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(N\\) 个副本加随机路由，共享前缀的命中期望被摊成 \\(1/N\\)：系统提示、工具说明书、长文档，每台各自算一遍。前缀命中省的是 P 池最贵的算力与用户可感的 TTFT。但反过来，纯缓存最优路由——永远打持有最长前缀的那台——会把热点节点打爆：局部性与均衡是两个目标，权重不是常数而是水位。第三个麻烦是视图：路由器的树是软状态，引擎在按自己的 LRU 驱逐，路由器不知道；<span class="marginnote">术语翻译：软状态就是「丢了也无妨、过期会自己被纠正的临时记录」。路由器手里的前缀树只是引擎真实缓存的近似影子——引擎随时在驱逐，影子随之变旧；所以命中信息只能拿来排序候选，不能当成铁的承诺。把它当硬承诺用，请求就会被派去一台其实早没这段缓存的机器。</span>拿过期视图做「最优」决策，比随机好不了多少。</p><h3 id="打分路由与水位折中" tabindex="-1">打分路由与水位折中 <a class="header-anchor" href="#打分路由与水位折中" aria-label="Permalink to &quot;打分路由与水位折中&quot;">​</a></h3><p>工程解是打分：\\(\\mathrm{score}=\\alpha\\cdot\\ell_{\\mathrm{hit}}-\\beta\\cdot q\\)，\\(\\ell_{\\mathrm{hit}}\\) 是候选副本上命中前缀的长度，\\(q\\) 是该副本的队列深度或 KV 水位。流程：按会话键（租户加会话 id，或最长公共前缀）在网关树上查候选，取分数最高者；命中副本全忙时，比较「等命中」与「去冷节点重算」——这就是 \\(\\alpha/\\beta\\) 的物理含义，且应动态：P 池越忙，\\(\\beta\\) 越大，越倾向重算也不排队。网关树要双向同步：引擎把驱逐与新增回报网关（或网关树带 TTL 衰减），把软状态当概率用——命中信息只影响排序，不做硬承诺。</p>',7)),(e(),B(i,null,{default:a(()=>[r(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%EF%BC%9A%E6%B6%88%E6%81%AF%E5%88%97%E8%A1%A8%22%5D%20--%3E%20KEY%5B%22%E4%BC%9A%E8%AF%9D%E9%94%AE%E4%B8%8E%E5%89%8D%E7%BC%80%E6%8C%87%E7%BA%B9%22%5D%0A%20%20KEY%20--%3E%20TREE%5B%22%E7%BD%91%E5%85%B3%E5%89%8D%E7%BC%80%E6%A0%91%EF%BC%9A%E6%9F%A5%E5%90%84%E5%89%AF%E6%9C%AC%E5%91%BD%E4%B8%AD%E9%95%BF%E5%BA%A6%22%5D%0A%20%20TREE%20--%3E%20CAND%5B%22%E5%80%99%E9%80%89%E9%9B%86%EF%BC%9A%E6%9C%89%E5%91%BD%E4%B8%AD%E8%80%85%22%5D%0A%20%20CAND%20--%3E%20SCORE%5B%22%E6%89%93%E5%88%86%EF%BC%9A%E5%91%BD%E4%B8%AD%E9%95%BF%E5%87%8F%E6%B0%B4%E4%BD%8D%E6%83%A9%E7%BD%9A%22%5D%0A%20%20SCORE%20--%3E%20PICK%7B%22%E6%9C%80%E9%AB%98%E5%88%86%E8%80%85%E5%BF%99%22%7D%0A%20%20PICK%20--%3E%7C%E4%B8%8D%E5%BF%99%7C%20GO%5B%22%E8%BD%AC%E5%8F%91%22%5D%0A%20%20PICK%20--%3E%7C%E5%BF%99%7C%20FB%7B%22%E7%AD%89%E5%91%BD%E4%B8%AD%E8%BF%98%E6%98%AF%E5%8E%BB%E5%86%B7%E8%8A%82%E7%82%B9%22%7D%0A%20%20FB%20--%3E%20GO%0A%20%20GO%20--%3E%20ENGINE%5B%22%E5%BC%95%E6%93%8E%EF%BC%9A%E6%9C%AC%E6%9C%BA%E6%A0%91%E5%86%8D%E7%B2%BE%E5%8C%B9%E9%85%8D%22%5D%0A%20%20ENGINE%20--%3E%20FBK%5B%22%E9%A9%B1%E9%80%90%E4%B8%8E%E6%96%B0%E5%A2%9E%E5%9B%9E%E6%8A%A5%E7%BD%91%E5%85%B3%22%5D%0A%20%20FBK%20--%3E%20TREE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>打分函数加软状态管理</strong>：把「命中与均衡怎么折中」落成一条可调的打分式——命中前缀长度减水位惩罚，\\(\\alpha\\) 与 \\(\\beta\\) 的比价含义是「等命中还是去冷节点重算」；<span class="marginnote">常见误区：初学者容易把「缓存命中率」当成唯一要最大化的数。但如果为了命中率把所有请求都派去同一个持有缓存的副本，P99 TTFT 会先爆掉——命中率和水位是两张都要付的账单，打分式里的 \\(\\beta\\) 就是这两张账单之间的汇率。</span>网关前缀树按软状态管：TTL 衰减加引擎回报驱逐与新增，命中信息只影响排序、不做硬承诺。方法论沿 KV 课程那句「命中靠放置」：路由器不制造缓存，只决定每段前缀在集群里的第二位作者。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>命中的收益可以显式定价：命中 \\(\\ell\\) 个 token 省 \\(\\ell/r_{\\mathrm{prefill}}\\) 的 P 池时间，叠加 TTFT 的直接改善——路由把「缓存」从单机优化变成放置问题，这正是 KV 课程那句「命中靠放置，不靠运气」的集群版。放置的极端是热前缀打满单机：此时正确动作不是让请求排队，也不是回退随机路由，而是<strong>复制热前缀</strong>到更多副本（<a href="/llm/prefix-aware-autoscaling">前缀感知扩缩容</a> 的思路），路由随之扩写。与公平的张力也要显式处理：亲和天然偏袒老会话——老会话持续命中，新会话总在冷节点起步；新会话的水位保底要写进打分，否则命中率报表与公平性报表打架。<span class="marginnote">直觉类比：会话亲和就像老顾客总去同一家分店，店员记得他的口味，点单又快又顺；但如果店就一个座位，新顾客全被挡在门外——所以得给新顾客留几个座位（水位保底），或者干脆把招牌菜的做法（热前缀）抄送几家新店（前缀复制）。</span></p><p>热前缀把单机打满时，三种缓解动作的代价完全不同：</p>',5)),(e(),B(i,null,{default:a(()=>[r(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOT%5B%22%E7%83%AD%E5%89%8D%E7%BC%80%EF%BC%9A%E5%91%BD%E4%B8%AD%E5%85%A8%E6%B6%8C%E5%90%91%E5%90%8C%E4%B8%80%E4%B8%AA%E5%89%AF%E6%9C%AC%22%5D%20--%3E%20FULL%7B%22%E8%AF%A5%E5%89%AF%E6%9C%AC%E6%B0%B4%E4%BD%8D%E8%B6%85%E9%99%90%EF%BC%9F%22%7D%0A%20%20FULL%20--%3E%7C%22%E5%90%A6%22%7C%20Q%5B%22%E6%AD%A3%E5%B8%B8%E6%89%93%E5%88%86%E8%B7%AF%E7%94%B1%22%5D%0A%20%20FULL%20--%3E%7C%22%E6%98%AF%22%7C%20C%7B%22%E9%80%89%E5%93%AA%E7%A7%8D%E7%BC%93%E8%A7%A3%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E8%AE%A9%E8%AF%B7%E6%B1%82%E6%8E%92%E9%98%9F%22%7C%20W%5B%22%E5%91%BD%E4%B8%AD%E7%8E%87%E5%A5%BD%E7%9C%8B%EF%BC%8C%E4%BD%86%20TTFT%20%E5%8F%98%E5%B7%AE%22%5D%0A%20%20C%20--%3E%7C%22%E5%9B%9E%E9%80%80%E9%9A%8F%E6%9C%BA%E8%B7%AF%E7%94%B1%22%7C%20R%5B%22%E5%91%BD%E4%B8%AD%E6%91%8A%E6%88%90%201%2FN%EF%BC%8CP%20%E6%B1%A0%E9%87%8D%E7%AE%97%E5%89%8D%E7%BC%80%22%5D%0A%20%20C%20--%3E%7C%22%E5%A4%8D%E5%88%B6%E7%83%AD%E5%89%8D%E7%BC%80%22%7C%20COPY%5B%22%E5%89%8D%E7%BC%80%E6%8A%84%E9%80%81%E5%88%B0%E6%9B%B4%E5%A4%9A%E5%89%AF%E6%9C%AC%22%5D%0A%20%20COPY%20--%3E%20S%5B%22%E8%B7%AF%E7%94%B1%E6%89%A9%E5%86%99%EF%BC%9A%E5%80%99%E9%80%89%E5%89%AF%E6%9C%AC%E5%8F%98%E5%A4%9A%22%5D%0A%20%20S%20--%3E%20Q%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">一个量级例：8 副本随机路由，8k 共享系统提示的命中期望是 1/8；每秒 8 条这样的流，P 池要烧约 10 卡秒每秒在重复前填上（单次 8k 前填按 6k token/s 约 1.3 s）。命中路由后降到约 1 卡秒每秒——省下的近九成算力，就是路由层这层软件的价值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>缓存键必须含租户（与适配器，见上一课）：跨租户命中是机密事故不是优化，网关树的分键要与引擎配额对齐。会话内多轮是亲和的最小受益单元（<a href="/llm/multi-turn-prefix">多轮前缀</a>），单轮请求的命中主要来自共享系统段。亲和与排干冲突：副本下线时（伸缩单元展开）会话要跟着搬，命中损失计入排干成本。路由器本身是新的故障域与延迟源：树操作必须是有界的 \\(O(\\ell)\\)，热路径上不做全树扫描。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机路由把命中摊成 \\(1/N\\)；缓存感知路由把命中变成放置决策。</li><li>打分 = 命中长度减水位惩罚；\\(\\alpha/\\beta\\) 的物理含义是「等命中与重算」的折中。</li><li>网关树是软状态：带 TTL 与回报机制，命中只排序、不做硬承诺。</li><li>热前缀打满单机时复制前缀，而不是排队或回退随机。</li><li>缓存键分租户分适配器；亲和要给新会话留水位保底。</li><li>出处：Kwon et al., SOSP 2023；SGLang Router 与 RadixAttention 的文档口径；前缀复制见站内前缀感知扩缩容专文。</li></ul>',5))])}const _=o(C,[["render",D]]);export{T as __pageData,_ as default};
